// Settings: describe your ideal customer profile here, then run.
//
// keyword       one term or a "quoted phrase". Avoid OR and -exclusions: those queries are slow and
//               often time out. Results are ranked by keyword match and company prominence.
// countries     ISO-2 codes, comma separated (for example 'US,GB'). Leave '' for any country.
// employeesMin / employeesMax   company size range (leave null for no limit).
// industries    optional, separated with | (must match the ReplyNodes industry names). Leave '' for any.
// maxPages      pages of 10 companies to fetch. Each page that returns companies costs 1 credit. Capped at 10.
return [
  {
    json: {
      keyword: 'carbon accounting software',
      countries: 'US',
      employeesMin: 11,
      employeesMax: 200,
      industries: '',
      maxPages: 5,
      apiBase: 'https://api.replynodes.com',
      spacingSeconds: 1.2,
      retryAfter504Seconds: 30,
      // Sent as the X-Source header so ReplyNodes can count usage of this template.
      sourceHeader: 'n8n-company-research/icp-list-builder',
    },
  },
];

// Build the loop state once: query parameters, page counter, and the domains already in the sheet
// (so the same company is never added twice).
function normalizeDomain(raw) {
  let s = String(raw ?? '').trim().toLowerCase();
  if (!s) return '';
  s = s.replace(/^[a-z][a-z0-9+.-]*:\/\//, ''); // protocol
  s = s.split(/[/?#]/)[0]; // path, query, hash
  s = s.replace(/^[^@]*@/, ''); // credentials
  s = s.replace(/:\d+$/, ''); // port
  s = s.replace(/\.$/, '').replace(/^www\./, '');
  return /^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$/.test(s) ? s : '';
}
const cfg = $('Settings').first().json;
const keyword = String(cfg.keyword ?? '').trim();
if (!keyword) throw new Error('Set a keyword in the Settings node.');

const baseQs = { query: keyword };
const countries = String(cfg.countries ?? '').replace(/\s+/g, '');
if (countries) baseQs.countries = countries;
if (cfg.employeesMin !== null && cfg.employeesMin !== '' && cfg.employeesMin !== undefined) baseQs.employees_min = cfg.employeesMin;
if (cfg.employeesMax !== null && cfg.employeesMax !== '' && cfg.employeesMax !== undefined) baseQs.employees_max = cfg.employeesMax;
const industries = String(cfg.industries ?? '').trim();
if (industries) baseQs.industries = industries;

const existing = $input.all().map((i) => normalizeDomain(i.json.domain)).filter(Boolean);
const maxPages = Math.min(Math.max(parseInt(cfg.maxPages, 10) || 5, 1), 10);

return [{ json: {
  baseQs,
  query: keyword,
  page: 1,
  cursor: '',
  attempt: 0,
  maxPages,
  seen: [...new Set(existing)],
  rows: [],
  skippedDuplicates: 0,
  pagesFetched: 0,
  stopReason: '',
  error: '',
  done: false,
  waitSeconds: 0,
} }];

// Read one page of results and decide what happens next: add rows, fetch the next page,
// retry once (429/503/504 or no response), or stop with a reason. Rows collected so far are never lost.
function normalizeDomain(raw) {
  let s = String(raw ?? '').trim().toLowerCase();
  if (!s) return '';
  s = s.replace(/^[a-z][a-z0-9+.-]*:\/\//, ''); // protocol
  s = s.split(/[/?#]/)[0]; // path, query, hash
  s = s.replace(/^[^@]*@/, ''); // credentials
  s = s.replace(/:\d+$/, ''); // port
  s = s.replace(/\.$/, '').replace(/^www\./, '');
  return /^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$/.test(s) ? s : '';
}
function companyToRow(c, loadedAt) {
  const funding = c.funding || {};
  const round = funding.latest_round || {};
  const hq = c.headquarters || {};
  const emp = c.employees || {};
  return {
    status: 'found',
    source: 'replynodes_db',
    name: c.name ?? '',
    description: c.description ?? '',
    industries: Array.isArray(c.industries) ? c.industries.join('; ') : '',
    hq_country: hq.country_code ?? '',
    hq_region: hq.region ?? '',
    employees_min: emp.min ?? '',
    employees_max: emp.max ?? '',
    funding_total_usd: funding.total_usd ?? '',
    latest_round_type: round.type ?? '',
    latest_round_date: round.date ?? '',
    data_loaded_at: loadedAt ?? '',
    checked_at: new Date().toISOString(),
    error: '',
  };
}
const st = $('Next request').item.json;
const cfg = $('Settings').first().json;
const res = $input.item.json;
const s = res.statusCode;
const body = res.body && typeof res.body === 'object' ? res.body : {};
const next = { ...st, rows: [...st.rows] };

if (s === 200 && body.data && Array.isArray(body.data.results)) {
  const seen = new Set(st.seen);
  for (const c of body.data.results) {
    const d = normalizeDomain(c.domain);
    if (!d || seen.has(d)) { next.skippedDuplicates += 1; continue; }
    seen.add(d);
    next.rows.push({ domain: d, ...companyToRow(c, body.data.loaded_at), query: st.query, page: st.page });
  }
  next.seen = [...seen];
  next.pagesFetched = st.page;
  next.attempt = 0;
  const cursor = (body.meta && body.meta.next_cursor) || '';
  if (!cursor) { next.done = true; next.stopReason = 'no more results'; }
  else if (st.page >= st.maxPages) { next.done = true; next.stopReason = 'reached max_pages (' + st.maxPages + ')'; }
  else { next.page = st.page + 1; next.cursor = cursor; next.done = false; next.waitSeconds = cfg.spacingSeconds; }
  return { json: next };
}

const retryable = !s || s === 429 || s === 503 || s === 504;
if (retryable && st.attempt === 0) {
  const retryAfter = parseInt((res.headers || {})['retry-after'], 10);
  const floor = s === 504 ? cfg.retryAfter504Seconds : 1;
  const base = s === 504 ? cfg.retryAfter504Seconds : 5;
  next.attempt = 1;
  next.done = false;
  next.waitSeconds = Math.min(Math.max(Number.isNaN(retryAfter) ? base : retryAfter, floor), 120);
  return { json: next };
}

const e = body.error || {};
let detail = !s ? ((res.error && (res.error.message || res.error.description)) || 'no response')
  : 'HTTP ' + s + (e.message ? ': ' + e.message : (e.code ? ': ' + e.code : ''));
if (s === 401) detail += ' (check the ReplyNodes API credential)';
if (s === 402) detail += ' (out of credits)';
if (s === 409) detail += ' (the cursor expired; run again)';
next.done = true;
next.error = detail + ' on page ' + st.page;
next.stopReason = 'stopped early: ' + next.error;
return { json: next };

// One item per new company.
const rows = $input.first().json.rows || [];
return rows.map((r) => ({ json: r }));

// What happened in this run (also visible if the list is empty).
const st = $input.first().json;
return [{ json: {
  pages_fetched: st.pagesFetched,
  companies_added: st.rows.length,
  duplicates_skipped: st.skippedDuplicates,
  stop_reason: st.stopReason,
  error: st.error,
} }];
